import os
from json import load
from random import randint
from re import match

from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_operation, log_step

from taf.rfrl.procedures.resources.python.vm import get_path_to_deltas_dir
from taf.rfrl.procedures.resources.python.json_delta_scf.exceptions import \
    IncorrectJsonDeltaFile


@log_input_and_output
def randomize_rmod_ids_in_delta_file(delta):
    """
    Finds changed rModIds in provided JSON delta file (in 'added' section), randomly selects new value for each of them
    and swaps old values with new values.
    Ensures, that random rModIds will not be consecutive numbers (i.e. 5, 6, 7).
    Random values are chosen from between minimal and maximal allowed rModId.
    Changes given JSON delta file IN PLACE, no copy will be created.

    How to properly create JSON delta file for this operation:

    1. Upload and activate base_scf (from SCF/5G dir in repo) on BTS
    2. Wait for onAir
    3. From WebUI manually change rModId values for each RU to some arbitrary numbers, i.e. 101, 102, 103, ...
    4. Activate changes
    5. Wait for onAir
    6. Download current SCF from BTS and save it as custom_scf
    7. Open CommonKeywords/RobotKeywords/DeltaScfGenerator.robot
    8. Set 'base_scf' and 'custom_scf' args with paths to used SCF files (base_scf and custom_scf respectively)
    9. Run 'Generate Delta' test case; used 'delta_file' arg should be passed to 'delta' arg in this function

    :param delta: name of JSON delta file (WITHOUT '.json' extension!) in which rModId values should be randomized;
                  exact path to file will be found automatically based on host name of current machine
    :type delta: str
    :raises IncorrectJsonDeltaFile: when JSON delta file with provided name doesn't exist (for current hostname) or
                                    it doesn't contain manually modified rModIds in 'added' section (see manual above)
    """
    log_operation('Changing rModIds in {} delta file to random values'.format(delta))
    delta_file_path = _get_delta_file_path(delta)
    old_rmod_ids = _get_old_rmod_ids(delta_file_path)
    new_rmod_ids = _randomize_rmod_ids(old_rmod_ids)
    new_json_delta_content = _generate_new_json_delta_content(delta_file_path, new_rmod_ids)
    _save_new_json_delta_content_into_file(delta_file_path, new_json_delta_content)


@log_input_and_output
def _get_delta_file_path(delta_name):
    delta_file_path = os.path.join(get_path_to_deltas_dir(), delta_name + '.json')

    if not os.path.isfile(delta_file_path):
        raise IncorrectJsonDeltaFile("JSON delta file '{}' doesn't exist".format(delta_file_path))

    return delta_file_path


@log_input_and_output
def _get_old_rmod_ids(delta_file_path):
    json_delta_content = _get_json_delta_content(delta_file_path)
    old_rmod_ids = []

    for added_item in json_delta_content.get('added', []):
        added_dist_name = added_item.get('dist_name', '')

        if match('^.*/RMOD-[0-9]+$', added_dist_name):
            old_rmod_ids.append(added_dist_name.split('/RMOD-')[1])

    if not old_rmod_ids:
        raise IncorrectJsonDeltaFile("JSON delta file doesn't contain changed rModIds. "
                                     "Make sure that it is generated from SCF with modified rModId value(s)")

    return old_rmod_ids


def _get_json_delta_content(delta_file_path):
    with open(delta_file_path) as delta_file:
        return load(delta_file)


@log_input_and_output
def _randomize_rmod_ids(old_rmod_ids):
    min_rmod_id = 1
    max_rmod_id = 32767
    new_rmod_ids = {}

    for old_rmod_id in old_rmod_ids:
        correct_new_rmod_id = False

        while not correct_new_rmod_id:
            new_rmod_id = randint(min_rmod_id, max_rmod_id)

            if (new_rmod_id - 1 not in new_rmod_ids.values() and new_rmod_id + 1 not in new_rmod_ids.values()) and \
                    (new_rmod_id != int(old_rmod_id)):
                new_rmod_ids[old_rmod_id] = new_rmod_id
                correct_new_rmod_id = True

    return new_rmod_ids


def _generate_new_json_delta_content(delta_file_path, new_rmod_ids):
    new_json_delta_content = []

    with open(delta_file_path) as old_json_delta_content:
        for line in old_json_delta_content:
            for old_rmod_id, new_rmod_id in new_rmod_ids.items():
                line = line.replace('RMOD-{}'.format(old_rmod_id),
                                    'RMOD-{}'.format(new_rmod_id))
            new_json_delta_content.append(line)

    return new_json_delta_content


def _save_new_json_delta_content_into_file(delta_file_path, new_json_delta_content):
    log_step('Saving {} delta with randomized rModIds'.format(delta_file_path))

    with open(delta_file_path, mode='w') as json_delta:
        json_delta.writelines(new_json_delta_content)
